  // ─── HTML Blocks (used with data-i18n-html) ────────────────────
  'help.install_app_html':
    'MUSIXQUARE ഇഷ്ടമായോ? ഇത് ഒരു ആപ്പായി ഇൻസ്റ്റാൾ ചെയ്യാം.<ul class="help-list"><li><strong>iOS:</strong> പങ്കിടുക → ഹോം സ്ക്രീനിലേക്ക് ചേർക്കുക</li><li><strong>Android:</strong> മെനു → ആപ്പ് ഇൻസ്റ്റാൾ ചെയ്യുക</li><li><strong>Windows:</strong> അഡ്രസ് ബാറിലെ ഇൻസ്റ്റാൾ ഐക്കൺ</li><li><strong>macOS:</strong> പങ്കിടുക → Dock-ലേക്ക് ചേർക്കുക</li></ul>',
  'help.local_recommended_html':
    'ഒരേ നെറ്റ്‌വർക്കിലാണ് ഓഡിയോ പങ്കിടൽ ഏറ്റവും സ്ഥിരതയോടെ പ്രവർത്തിക്കുന്നത്.<ul class="help-list"><li>റിമോട്ട് പങ്കാളികൾക്കും അതേ സവിശേഷതകൾ ഉപയോഗിക്കാം.</li><li>റിമോട്ട് പങ്കാളികൾ Cloudflare പാതകൾ ഉപയോഗിക്കുന്നതിനാൽ നെറ്റ്‌വർക്ക് സാഹചര്യങ്ങൾക്കനുസരിച്ച് കാലതാമസം കൂടുകയോ സ്വീകരിക്കൽ പരാജയപ്പെടുകയോ ചെയ്യാം.</li><li>VPN അല്ലെങ്കിൽ നിയന്ത്രിത നെറ്റ്‌വർക്ക് ബന്ധം അസ്ഥിരമാക്കിയേക്കാം.</li></ul>',
  'setup.how_to_connect_html':
    'ബന്ധിപ്പിക്കാൻ ഹോസ്റ്റിൽ നിന്നുള്ള <strong>6 അക്ക കോഡ്</strong> നൽകുക.<ul class="help-list"><li><strong>ഹോസ്റ്റ്:</strong> “ഞാൻ ഹോസ്റ്റാകും” → കോഡ് പരിശോധിക്കുക</li><li><strong>പങ്കാളി:</strong> “ഒരു സെഷനിൽ ചേരുക” → കോഡ് നൽകുക</li><li><strong>ഹോസ്റ്റ് ഉൾപ്പെടെ പരമാവധി 100 ഡിവൈസുകൾക്ക്</strong> ബന്ധിപ്പിക്കാം.</li></ul>',
  'player.play_speakers_html':
    'ഓരോ പങ്കാളിയും ഒരു <strong>റോൾ (ഔട്ട്‌പുട്ട് ചാനൽ)</strong> തിരഞ്ഞെടുക്കുന്നു.<ul class="help-list"><li><strong>മധ്യം:</strong> സ്റ്റീരിയോ (ഡിഫോൾട്ട്) ഔട്ട്‌പുട്ട്</li><li><strong>ഇടത്:</strong> <bdi dir="ltr">L</bdi> ചാനൽ ഔട്ട്‌പുട്ട്</li><li><strong>വലത്:</strong> <bdi dir="ltr">R</bdi> ചാനൽ ഔട്ട്‌പുട്ട്</li><li><strong>സബ്‌വൂഫർ:</strong> താഴ്ന്ന ആവൃത്തി മിക്സ് ഔട്ട്‌പുട്ട്</li></ul><strong>ക്രമീകരണങ്ങളിൽ</strong> എപ്പോൾ വേണമെങ്കിലും റോളുകൾ മാറ്റാം.',
  'player.play_media_action_html':
    'ഹോസ്റ്റിന് 3 ഓപ്ഷനുകളുണ്ട്.<ul class="help-list"><li><strong>ലോക്കൽ ഫയൽ ലോഡ് ചെയ്യുക:</strong> നിങ്ങളുടെ ഡിവൈസിൽ നിന്ന് സംഗീതം തിരഞ്ഞെടുക്കുക. കൃത്യമായ സിങ്ക് പിന്തുണയ്ക്കുന്നു</li><li><strong>ഒരുമിച്ച് YouTube:</strong> വീഡിയോകളും പ്ലേലിസ്റ്റുകളും പിന്തുണയ്ക്കുന്നു. ചാനൽ വേർതിരിക്കലോ ഓഡിയോ ഇഫക്റ്റുകളോ ഇല്ല</li><li><strong>സിസ്റ്റം ഓഡിയോ പങ്കിടൽ:</strong> ഹോസ്റ്റ് കമ്പ്യൂട്ടറിൽ Chromium അടിസ്ഥാനമാക്കിയുള്ള ബ്രൗസർ ഉപയോഗിക്കുമ്പോൾ ലഭ്യമാണ്</li></ul>',
  'help.need_help_html':
    '<ul class="help-list"><li><strong>കോഡ് നൽകിയിട്ടും ബന്ധിപ്പിക്കാനാകുന്നില്ല:</strong> കോഡ് പരിശോധിച്ച് അൽപ്പസമയത്തിനകം വീണ്ടും ശ്രമിക്കുക. കമ്പനി, സ്കൂൾ, VPN നെറ്റ്‌വർക്കുകൾ ബന്ധം നിയന്ത്രിച്ചേക്കാം.</li><li><strong>അസ്ഥിരമായ ബന്ധം:</strong> ലോക്കൽ പങ്കാളികൾ റൂട്ടറിനടുത്ത് തുടരാൻ ശ്രമിക്കുകയും റിമോട്ട് പങ്കാളികൾ സ്ഥിരതയുള്ള ഇന്റർനെറ്റ് ബന്ധം ഉപയോഗിക്കുകയും വേണം.</li><li><strong>മറ്റ് പ്രശ്നങ്ങൾ:</strong> നെറ്റ്‌വർക്ക് നില പരിശോധിച്ച് എല്ലാ ഡിവൈസുകളിലും ആപ്പ് പുനരാരംഭിക്കുക. ചോദ്യങ്ങളുണ്ടെങ്കിൽ <a href="/faq" target="_blank" rel="noopener noreferrer" style="color:inherit;text-decoration:underline">FAQ</a> കാണുക അല്ലെങ്കിൽ ഏറ്റവും താഴെയുള്ള ഇമെയിൽ വഴി ബന്ധപ്പെടുക.</li></ul>',
